import { GenerationParams } from '../types/template';

// Mock AI content generator for pharmaceutical strategy templates
export const generateContent = async (
  templateId: string,
  inputs: Record<string, string>,
  params: GenerationParams
): Promise<Record<string, string>> => {
  // Simulate API delay
  await new Promise(resolve => setTimeout(resolve, 1500));

  const generators: Record<string, (inputs: Record<string, string>, params: GenerationParams) => Record<string, string>> = {
    'situational-analysis': generateSituationalAnalysis,
    'market-shaping-matrix': generateMarketShapingMatrix,
    'stakeholder-matrix': generateStakeholderMatrix,
    'stakeholder-pyramid': generateStakeholderPyramid,
    'competitor-mapping': generateCompetitorMapping,
    'think-feel-do': generateThinkFeelDo,
    'mindshift-map': generateMindshiftMap,
    'disease-model': generateDiseaseModel,
    'clinical-treatment-flow': generateClinicalTreatmentFlow,
    'patient-journey': generatePatientJourney,
    'swot': generateSWOT,
    'scientific-focus': generateScientificFocus,
    'target-product-profile': generateTargetProductProfile,
    'pgmi': generatePGMI,
    'scientific-strategic-framework': generateScientificStrategicFramework,
    'scientific-story': generateScientificStory
  };

  const generator = generators[templateId];
  if (!generator) {
    throw new Error('Template not found');
  }

  return generator(inputs, params);
};

function generateSituationalAnalysis(inputs: Record<string, string>, params: GenerationParams): Record<string, string> {
  const { therapeuticArea, marketContext, keyFactors } = inputs;
  
  return {
    executiveSummary: `The ${therapeuticArea} market is experiencing significant transformation driven by evolving treatment paradigms and competitive dynamics. ${marketContext}`,
    
    marketOverview: `Current Market Landscape:\n\n• Market size continues to grow with increasing patient identification\n• Treatment algorithms are shifting based on new clinical evidence\n• Payer landscape becoming more restrictive with value-based requirements\n• Competitive entry creating pressure on market share and pricing`,
    
    internalFactors: `Strengths:\n• Strong clinical data supporting efficacy claims\n• Established medical affairs infrastructure\n• Positive KOL relationships and scientific credibility\n\nWeaknesses:\n• Limited real-world evidence vs. competitors\n• Manufacturing capacity constraints\n• Market access challenges in key regions`,
    
    externalFactors: `Opportunities:\n• Expanding patient population and improved diagnostics\n• New clinical guidelines favoring mechanism of action\n• Potential label expansion to earlier lines of therapy\n\nThreats:\n• Generic competition and biosimilar entry\n• Changing treatment paradigms\n• Regulatory scrutiny on safety signals\n• Healthcare reform and pricing pressure`,
    
    criticalFactors: `Based on analysis of ${keyFactors}, the following priorities emerge:\n\n1. Strengthen value proposition with health economics data\n2. Build real-world evidence to support clinical claims\n3. Enhance stakeholder engagement across continuum\n4. Develop defensive strategies against competitive threats`,
    
    recommendations: `Strategic Imperatives:\n• Accelerate real-world evidence generation program\n• Invest in outcomes research demonstrating long-term value\n• Proactively address emerging safety concerns\n• Optimize pricing and market access strategy by segment`
  };
}

function generateMarketShapingMatrix(inputs: Record<string, string>, params: GenerationParams): Record<string, string> {
  const { marketSegment, stakeholders, objectives } = inputs;
  
  return {
    overview: `Market shaping strategy for ${marketSegment} focusing on influencing key stakeholder perceptions and treatment paradigms.`,
    
    currentState: `Current Market Perceptions:\n• Standard of care defined by established therapies\n• Clinical decision-making driven by safety-first approach\n• Payers prioritizing cost over innovation\n• Limited awareness of disease burden among patients`,
    
    shapingOpportunities: `Key Shaping Opportunities:\n\n1. Clinical Guidelines\n   • Engage guideline committees with emerging evidence\n   • Position data at medical congresses\n   • Support real-world research on optimal sequencing\n\n2. Payer Landscape\n   • Develop compelling value dossiers\n   • Demonstrate budget impact and cost-effectiveness\n   • Create patient access programs\n\n3. Treatment Paradigm\n   • Educate on earlier intervention benefits\n   • Shift conversation from symptom management to disease modification\n   • Build advocacy for personalized medicine approaches`,
    
    stakeholderStrategies: `Stakeholder Engagement:\n\n${stakeholders}\n\nFor each group:\n• Map current beliefs and desired mindset shifts\n• Identify key influencers and decision-makers\n• Develop targeted scientific narratives\n• Create engagement opportunities and touchpoints`,
    
    tactics: `Implementation Tactics:\n• Medical education initiatives and symposia\n• Publication strategy in high-impact journals\n• Advisory board series with key opinion leaders\n• Patient education and disease awareness campaigns\n• Health economics research partnerships`,
    
    objectives: `Success Metrics:\n\n${objectives}\n\nKey Performance Indicators:\n• Treatment pattern evolution toward preferred positioning\n• Guideline recommendation updates\n• Improved formulary status and access\n• Increased disease awareness and diagnosis rates`,
    
    timeline: `Phased Approach:\n\nYear 1: Foundation building - evidence generation, stakeholder mapping\nYear 2: Active shaping - guideline engagement, publication execution\nYear 3: Market transformation - sustained thought leadership, paradigm shift`
  };
}

function generateStakeholderMatrix(inputs: Record<string, string>, params: GenerationParams): Record<string, string> {
  const { project, stakeholderGroups, priorities } = inputs;
  
  return {
    overview: `Comprehensive stakeholder mapping and engagement strategy for ${project}.`,
    
    stakeholderSegmentation: `Key Stakeholder Groups:\n\n${stakeholderGroups}\n\nSegmented by:\n• Power/Influence level\n• Interest/Impact on project\n• Current disposition (supporter/neutral/detractor)\n• Engagement readiness`,
    
    powerInterestMatrix: `High Power / High Interest (Key Players):\n• Executive decision-makers\n• Key opinion leaders in field\n• Major payer organizations\n• Regulatory authorities\n\nHigh Power / Low Interest (Keep Satisfied):\n• Senior leadership\n• Healthcare system administrators\n• Policy makers\n\nLow Power / High Interest (Keep Informed):\n• Patient advocacy groups\n• Healthcare practitioners\n• Academic researchers\n\nLow Power / Low Interest (Monitor):\n• General medical community\n• Adjacent specialty groups`,
    
    engagementStrategy: `Priority Stakeholder Strategies:\n\n1. Key Opinion Leaders\n   • Establish advisory relationships\n   • Co-develop research initiatives\n   • Support thought leadership platforms\n   • Seek input on strategic decisions\n\n2. Payers & Administrators\n   • Present health economic value\n   • Demonstrate budget impact\n   • Negotiate value-based agreements\n   • Provide outcomes data\n\n3. Regulatory Bodies\n   • Maintain transparent communication\n   • Proactively address concerns\n   • Submit robust evidence packages\n   • Plan for label optimization`,
    
    prioritization: `Prioritization Framework:\n\n${priorities}\n\nRanking Criteria:\n• Strategic importance to project success\n• Urgency of engagement\n• Resource requirements\n• Potential barriers or risks`,
    
    actionPlan: `90-Day Action Items:\n• Complete stakeholder identification and mapping\n• Conduct initial outreach to tier-1 stakeholders\n• Develop tailored engagement plans by segment\n• Establish success metrics and tracking\n• Create escalation paths for critical stakeholders`,
    
    riskMitigation: `Risk Management:\n• Identify potential detractors and develop response plans\n• Monitor competitive stakeholder engagement\n• Build coalition of supporters\n• Prepare for scenarios where key stakeholders oppose project`
  };
}

function generateStakeholderPyramid(inputs: Record<string, string>, params: GenerationParams): Record<string, string> {
  const { initiative, topTier, engagementGoals } = inputs;
  
  return {
    overview: `Hierarchical stakeholder engagement framework for ${initiative} prioritizing resources and attention based on strategic value.`,
    
    tier1TopPriority: `Tier 1 - Strategic Partners (Top Priority):\n\n${topTier}\n\nEngagement Approach:\n• Direct executive-level relationships\n• Customized scientific and strategic discussions\n• Co-creation opportunities\n• Quarterly strategic reviews\n• First access to data and insights\n\nTime Investment: 40% of engagement resources`,
    
    tier2HighPriority: `Tier 2 - Key Influencers:\n\n• National/Regional KOLs\n• Payer medical directors\n• Major academic institutions\n• Large integrated delivery networks\n\nEngagement Approach:\n• Advisory boards and expert panels\n• Speaking opportunities\n• Research collaborations\n• Bi-annual touchpoints\n\nTime Investment: 35% of engagement resources`,
    
    tier3Medium: `Tier 3 - Important Stakeholders:\n\n• Community practice leaders\n• Specialty pharmacies\n• Patient advocacy organizations\n• Regional health systems\n\nEngagement Approach:\n• Educational programs\n• Peer-to-peer forums\n• Digital engagement platforms\n• Annual meetings\n\nTime Investment: 20% of engagement resources`,
    
    tier4Broad: `Tier 4 - General Awareness:\n\n• General practitioner community\n• Allied health professionals\n• Patient populations\n• General scientific community\n\nEngagement Approach:\n• Mass education campaigns\n• Digital content and resources\n• Conference exhibitions\n• On-demand materials\n\nTime Investment: 5% of engagement resources`,
    
    objectives: `Engagement Objectives by Tier:\n\n${engagementGoals}\n\nMeasurement Framework:\n• Tier 1: Strategic alignment, advocacy, co-creation outcomes\n• Tier 2: Adoption rates, recommendation patterns\n• Tier 3: Awareness, education completion\n• Tier 4: Reach, engagement metrics`,
    
    movementStrategy: `Tier Movement Strategy:\n• Define criteria for tier elevation\n• Create pathways for stakeholder progression\n• Regular review and re-segmentation\n• Recognize and respond to changing influence`,
    
    resourceAllocation: `Budget and Resource Planning:\n• Field team deployment aligned to pyramid\n• Technology investments for scale (lower tiers)\n• Premium experiences for top tiers\n• Content and materials tailored by level`
  };
}

function generateCompetitorMapping(inputs: Record<string, string>, params: GenerationParams): Record<string, string> {
  const { indication, competitors, dimensions } = inputs;
  
  return {
    overview: `Competitive intelligence analysis for ${indication} market, mapping key competitors across strategic dimensions: ${dimensions}.`,
    
    competitiveSet: `Primary Competitors:\n\n${competitors}\n\nSecondary/Emerging Threats:\n• Generic and biosimilar entrants\n• New mechanism therapies in development\n• Adjacent indication expansions\n• Treatment modality alternatives`,
    
    productComparison: `Comparative Product Profiles:\n\nEfficacy Positioning:\n• Best-in-class demonstrated outcomes vs. standard metrics\n• Head-to-head trial results and indirect comparisons\n• Subgroup analyses and responder rates\n• Long-term durability of response data\n\nSafety Profile:\n• Adverse event rates and severity distribution\n• Tolerability and discontinuation patterns\n• Black box warnings and label restrictions\n• Long-term safety surveillance findings`,
    
    marketPositioning: `Market Position Analysis:\n\nCurrent Market Share:\n• Volume and value share by segment\n• Growth trajectories and momentum\n• Geographic strongholds and weaknesses\n\nPricing & Access:\n• List price and net price positioning\n• Formulary placement and restrictions\n• Patient assistance program competitiveness\n• Value-based contracting adoption`,
    
    clinicalDifferentiation: `Clinical Differentiation Opportunities:\n\n• Mechanism of action advantages\n• Patient population targeting (precision medicine)\n• Combination therapy compatibility\n• Dosing convenience and administration\n• Onset of action and time to response\n• Quality of life and patient-reported outcomes`,
    
    strategicPositioning: `Recommended Positioning:\n\nVs. Market Leader:\n• Emphasize safety/tolerability advantages\n• Target patients with specific comorbidities\n• Position for earlier line of therapy\n\nVs. New Entrants:\n• Leverage real-world evidence and experience\n• Highlight proven long-term outcomes\n• Defend with comprehensive support programs`,
    
    competitiveThreats: `Threat Assessment:\n\nImmediate (0-12 months):\n• Competitor label expansion approval\n• New head-to-head trial data presentation\n• Major payer contract wins by competitors\n\nNear-term (1-2 years):\n• Pipeline asset approvals\n• Generic/biosimilar entry\n• Treatment guideline updates`,
    
    recommendations: `Strategic Response Plan:\n• Accelerate evidence generation in key differentiation areas\n• Develop proactive competitive response materials\n• Enhance medical education on comparative benefits\n• Strengthen payer relationships with value story`
  };
}

function generateThinkFeelDo(inputs: Record<string, string>, params: GenerationParams): Record<string, string> {
  const { audience, journey, currentState } = inputs;
  
  return {
    overview: `Customer journey analysis for ${audience} at ${journey} stage, mapping cognitive, emotional, and behavioral dimensions.`,
    
    currentState: `Current State Assessment:\n\n${currentState}`,
    
    thinkCognitive: `THINK (Cognitive Dimension):\n\nCurrent Beliefs:\n• "Standard therapies are adequate for most patients"\n• "New treatments carry unknown risks"\n• "Clinical trial data may not reflect real-world practice"\n• "Cost considerations limit treatment options"\n\nKnowledge Gaps:\n• Limited awareness of disease progression without optimal treatment\n• Incomplete understanding of mechanism differentiation\n• Insufficient familiarity with long-term outcome data\n\nInformation Needs:\n• Comparative effectiveness evidence\n• Safety profile in relevant patient populations\n• Practical implementation guidance\n• Health economic value proposition`,
    
    feelEmotional: `FEEL (Emotional Dimension):\n\nCurrent Emotions:\n• Cautious about changing established practice patterns\n• Overwhelmed by volume of new therapeutic options\n• Skeptical of marketing claims vs. clinical reality\n• Frustrated with administrative burden of new treatments\n\nEmotional Barriers:\n• Fear of adverse outcomes with unfamiliar therapy\n• Anxiety about patient access and affordability\n• Doubt about personal ability to identify appropriate patients\n\nDesired Emotional State:\n• Confidence in treatment decisions\n• Enthusiasm for improved patient outcomes\n• Trust in scientific evidence and support\n• Empowerment through knowledge and resources`,
    
    doBehavioral: `DO (Behavioral Dimension):\n\nCurrent Behaviors:\n• Prescribing established first-line therapies by default\n• Reserving new treatments for treatment-experienced patients\n• Referring complex cases to specialists\n• Limiting use due to administrative requirements\n\nBehavioral Barriers:\n• Inertia of clinical practice routines\n• Reimbursement and prior authorization hurdles\n• Time constraints for patient education\n• Lack of office protocols for new therapy initiation\n\nTarget Behaviors:\n• Proactive patient identification and assessment\n• Earlier consideration of optimal therapy\n• Routine discussion of treatment options with patients\n• Integration into clinical pathways and protocols`,
    
    interventionStrategy: `Intervention Strategy:\n\nThink Interventions:\n• Medical education on evidence and guidelines\n• Case studies demonstrating real-world outcomes\n• Comparative data presentations\n• Decision support tools\n\nFeel Interventions:\n• Peer testimonials and success stories\n• Risk mitigation resources (e.g., monitoring guidance)\n• Patient support program assurance\n• Responsive medical information team\n\nDo Interventions:\n• Simplified patient identification tools\n• Office implementation resources\n• Reimbursement support services\n• Digital prescribing aids`,
    
    journeyOptimization: `Journey Stage Optimization:\n\nAwareness → Interest:\n• Targeted congress presence and symposia\n• Publication in key journals\n• KOL advocacy and presentations\n\nInterest → Consideration:\n• In-depth clinical data discussions\n• Advisory board participation\n• One-on-one field engagement\n\nConsideration → Adoption:\n• Patient starter programs\n• Co-pay assistance transparency\n• Implementation support\n• Early patient success follow-up\n\nAdoption → Advocacy:\n• Ongoing outcomes sharing\n• Speaker program opportunities\n• Research collaboration invitations`
  };
}

